<?= view('partials/header', ['title' => $title]) ?>
<div class="page-head row"><div><p class="eyebrow">MANAGEMENT</p><h1>Task List</h1><p>Active tasks are shown below. Archived tasks are hidden.</p></div><?php if (session()->get('isLoggedIn')): ?><a class="button" href="<?= site_url('tasks/new') ?>">+ New Task</a><?php endif; ?></div>
